function generatePermutations($n, $k) {
    $result = [];
    $current = [];
    $used = array_fill(0, $n + 1, false);
    generate($n, $k, 1, $current, $used, $result);
    return $result;
}

function generate($n, $k, $start, &$current, &$used, &$result) {
    if (count($current) == $n) {
        $result[] = $current;
        return;
    }
    for ($i = $start; $i <= $n; $i++) {
        if (!$used[$i]) {
            $cycle = [];
            $cycle[] = $i;
            $used[$i] = true;
            $current[] = $i;
            generateCycle($n, $i, $cycle, $used, $current, $result);
            array_pop($current);
            $used[$i] = false;
        }
    }
}

function generateCycle($n, $prev, &$cycle, &$used, &$current, &$result) {
    if (count($cycle) >= 2) {
        $last = $cycle[count($cycle) - 1];
        $current[] = $last;
        $used[$last] = true;
        generateCycle($n, $last, $cycle, $used, $current, $result);
        array_pop($current);
        $used[$last] = false;
    }
    for ($i = 1; $i <= $n; $i++) {
        if (!$used[$i] && $i < $prev) {
            $cycle[] = $i;
            $used[$i] = true;
            generateCycle($n, $i, $cycle, $used, $current, $result);
            array_pop($cycle);
            $used[$i] = false;
        }
    }
    if (count($cycle) >= 1) {
        $result[] = $current;
    }
}

function main() {
    $input = trim(file_get_contents("php://stdin"));
    list($n, $k) = explode(' ', $input);
    $n = (int)$n;
    $k = (int)$k;

    $perms = generatePermutations($n, $k);
    if ($k <= count($perms)) {
        echo implode(' ', $perms[$k - 1]) . "\n";
    } else {
        echo "Not enough permutations\n";
    }
}

main();
?>
