<?php

function find_kth_permutation($n, $k) {
    $result = [];
    $available = range(1, $n);
    $k--;
    $factorial = 1;
    for ($i = 1; $i <= $n; $i++) {
        $factorial *= $i;
    }
    for ($i = 0; $i < $n; $i++) {
        $factorial = (int)($factorial / ($n - $i));
        $index = (int)($k / $factorial);
        $result[] = $available[$index];
        array_splice($available, $index, 1);
        $k %= $factorial;
    }
    return $result;
}

function is_fixed_permutation($p) {
    $n = count($p);
    $visited = array_fill(0, $n, false);
    for ($i = 0; $i < $n; $i++) {
        if (!$visited[$i]) {
            $cycle = [];
            $current = $i;
            while (!$visited[$current]) {
                $visited[$current] = true;
                $cycle[] = $current + 1;
                $current = $p[$current] - 1;
            }
            $max_val = max($cycle);
            $max_pos = array_search($max_val, $cycle);
            $rotated = array_merge(array_slice($cycle, $max_pos), array_slice($cycle, 0, $max_pos));
            if ($rotated !== $cycle) {
                return false;
            }
        }
    }
    return true;
}

function generate_fixed_permutations($n) {
    $perms = [];
    $total = 1;
    for ($i = 2; $i <= $n; $i++) {
        $total *= $i;
    }
    for ($i = 0; $i < $total; $i++) {
        $perm = find_kth_permutation($n, $i + 1);
        if (is_fixed_permutation($perm)) {
            $perms[] = $perm;
        }
    }
    usort($perms, function($a, $b) {
        for ($i = 0; $i < count($a); $i++) {
            if ($a[$i] != $b[$i]) {
                return $a[$i] - $b[$i];
            }
        }
        return 0;
    });
    return $perms;
}

function solve($n, $k) {
    $perms = generate_fixed_permutations($n);
    if ($k <= count($perms)) {
        return $perms[$k - 1];
    }
    return [];
}

