    $line = trim(fgets(STDIN));
    list($n, $k) = array_map('intval', explode(' ', $line));

    $result = generate($n, $k);
    echo implode(' ', $result) . "\n";
}

function generate($n, $k) {
    $perm = array_fill(0, $n, 0);
    $used = array_fill(0, $n + 1, false); // 1-based
    $current = 1;
    $k--;
    if ($k < 0) return $perm;

    for ($pos = 0; $pos < $n; $pos++) {
        $start = ($pos == 0) ? 1 : $perm[$pos - 1] + 1;
        for ($num = $start; $num <= $n; $num++) {
            if ($used[$num]) continue;
            $used[$num] = true;
            $count = countPermutations($n, $pos + 1, $num, $used);
            if ($count > $k) {
                $perm[$pos] = $num;
                break;
            }
            $k -= $count;
            $used[$num] = false;
        }
    }
    return $perm;
}

function countPermutations($n, $pos, $max_so_far, $used) {
    if ($pos == $n) return 1;
    $total = 0;
    $start = $max_so_far + 1;
    for ($num = $start; $num <= $n; $num++) {
        if ($used[$num]) continue;
        $used[$num] = true;
        $total += countPermutations($n, $pos + 1, $num, $used);
        $used[$num] = false;
    }
    return $total;
}

