function backtrack($n, &$used, &$current, &$valid) {
    if (count($current) === $n) {
        if (isValid($current)) {
            $valid[] = $current;
        }
        return;
    }

    for ($i = 1; $i <= $n; $i++) {
        if (!$used[$i]) {
            $used[$i] = true;
            $current[] = $i;
            backtrack($n, $used, $current, $valid);
            array_pop($current);
            $used[$i] = false;
        }
    }
}

function isValid($p) {
    $n = count($p);
    $visited = array_fill(0, $n, false);
    $cycles = [];

    for ($i = 0; $i < $n; $i++) {
        if (!$visited[$i]) {
            $cycle = [];
            $j = $i;
            while (!$visited[$j]) {
                $visited[$j] = true;
                $cycle[] = $j + 1; // 1-based index
                $j = $p[$j] - 1; // p[j] is 1-based value
            }
            // Normalize cycle: rotate so max is first
            $maxVal = max($cycle);
            $maxIdx = array_search($maxVal, $cycle);
            $normalized = array_merge(
                array_slice($cycle, $maxIdx),
                array_slice($cycle, 0, $maxIdx)
            );
            $cycles[] = $normalized;
        }
    }

    // Sort cycles by first element
    usort($cycles, function($a, $b) {
        return $a[0] - $b[0];
    });

    // Build the standard cyclic representation string
    $standard = [];
    foreach ($cycles as $cycle) {
        foreach ($cycle as $val) {
            $standard[] = $val;
        }
    }

    // Compare with original permutation
    return $standard === $p;
}

